#include "TestSupport.h"
#include "../src/Core/Engine.h"
#include "../src/Player/Player.h"
struct GraphicsTestAccess { static bool Click(Graphics&g,float x,float y){return g.HandleShopClick(x,y);} };
struct EngineTestAccess { static bool Init(Engine&e){return e.InitializeWorldForRun();} static World&W(Engine&e){return e.world;} static Graphics&G(Engine&e){return e.graphics;} static int Player(Engine&e){return e.playerID;} static bool Enqueue(Engine&e){return e.EnqueuePendingShopCommand();} static void Sync(Engine&e){e.SynchronizeShopPresentation();} static std::uint64_t Pending(Engine&e){return e.pendingShopCommandID;} };
struct WorldTestAccess { static void Inject(World&w,CommandProcessingResult r){w.publishedCommandProcessingResults.push_back(r);} };
int main(){ TestContext t; Engine e; t.Expect(EngineTestAccess::Init(e),"Engine initializes"); auto&w=EngineTestAccess::W(e); auto&g=EngineTestAccess::G(e); int p=EngineTestAccess::Player(e); auto*player=dynamic_cast<Player*>(w.GetEntityByID(p)); player->GetPosition().SetPosition(2,3); player->GetInventory().AddItem(ItemType::COINS,8); player->GetInventory().AddItem(ItemType::COOKED_MEAT,1); w.EnqueueCommand(NpcInteractionCommand{p,1,NpcInteractionType::TRADE}); w.Update(); t.Expect(!w.GetShopOpenedEvents().empty(),"Trade session opens after World tick"); g.SynchronizeShop(p,w.GetShopOpenedEvents(),w.GetActiveShopSession(p)); auto row=g.GetShopRowRectangle(0); GraphicsTestAccess::Click(g,row.x+row.w-250,row.y+row.h/2); t.Expect(EngineTestAccess::Enqueue(e),"Buy queues from SDL hitbox"); auto before=player->GetInventory().GetItemAmount(ItemType::COOKED_MEAT); w.Update(); t.Expect(player->GetInventory().GetItemAmount(ItemType::COINS)==0&&player->GetInventory().GetItemAmount(ItemType::COOKED_MEAT)==before+1,"Accepted buy applies on World tick"); EngineTestAccess::Sync(e); player->GetInventory().AddItem(ItemType::COOKED_MEAT,1); GraphicsTestAccess::Click(g,row.x+row.w-100,row.y+row.h/2); t.Expect(EngineTestAccess::Enqueue(e),"Sell queues from SDL hitbox"); w.Update(); t.Expect(player->GetInventory().GetItemAmount(ItemType::COOKED_MEAT)==before+1&&player->GetInventory().GetItemAmount(ItemType::COINS)==3,"Accepted sell applies on World tick"); EngineTestAccess::Sync(e); const int coins=player->GetInventory().GetItemAmount(ItemType::COINS), meat=player->GetInventory().GetItemAmount(ItemType::COOKED_MEAT); GraphicsTestAccess::Click(g,row.x+row.w-250,row.y+row.h/2); t.Expect(EngineTestAccess::Enqueue(e),"Rejected buy queues from SDL hitbox"); auto id=EngineTestAccess::Pending(e); w.Update(); WorldTestAccess::Inject(w,{id,p,CommandResultCode::GAMEPLAY_REJECTED}); EngineTestAccess::Sync(e); t.Expect(player->GetInventory().GetItemAmount(ItemType::COINS)==coins&&player->GetInventory().GetItemAmount(ItemType::COOKED_MEAT)==meat&&g.GetShopPresentationState().IsOpen()&&g.GetShopPresentationState().HasRejection(),"Rejected buy preserves state and feedback"); return t.Finish(); }
